"""Database schema.

Conventions:

* UUID primary keys, generated by the app (or by Postgres for raw inserts).
* Every timestamp is ``timestamptz``.
* Status-like columns are text with a CHECK constraint built from the domain enums:
  as safe as a Postgres ENUM, but adding a value is a one-line migration.
* Every tenant-owned table carries ``org_id`` so queries can always be scoped to
  the organisation without joins.
"""

import uuid
from datetime import datetime
from enum import StrEnum
from typing import Annotated, Any

from sqlalchemy import (
    CheckConstraint,
    DateTime,
    ForeignKey,
    Index,
    MetaData,
    String,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

from relay.domain.enums import BreakerState, DeliveryStatus, EndpointStatus, ErrorKind, Role

# Explicit constraint names make migrations deterministic and errors readable.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


def _one_of(column: str, enum: type[StrEnum]) -> str:
    values = ", ".join(f"'{member.value}'" for member in enum)
    return f"{column} IN ({values})"


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)
    type_annotation_map = {  # noqa: RUF012 - SQLAlchemy reads this class attribute
        datetime: DateTime(timezone=True),
        dict[str, Any]: JSONB,
    }


UuidPk = Annotated[
    uuid.UUID,
    mapped_column(primary_key=True, default=uuid.uuid4, server_default=text("gen_random_uuid()")),
]
CreatedAt = Annotated[datetime, mapped_column(server_default=func.now())]


def _fk(target: str, *, ondelete: str = "CASCADE") -> ForeignKey:
    return ForeignKey(target, ondelete=ondelete)


# --------------------------------------------------------------------- tenancy
class Organization(Base):
    __tablename__ = "organizations"

    id: Mapped[UuidPk]
    name: Mapped[str] = mapped_column(String(200))
    created_at: Mapped[CreatedAt]


class User(Base):
    __tablename__ = "users"

    id: Mapped[UuidPk]
    # Stored lower-cased by the application, so the unique constraint is
    # effectively case-insensitive.
    email: Mapped[str] = mapped_column(String(320), unique=True)
    password_hash: Mapped[str] = mapped_column(Text)
    created_at: Mapped[CreatedAt]

    __table_args__ = (CheckConstraint("email = lower(email)", name="email_lowercase"),)


class Membership(Base):
    __tablename__ = "memberships"

    user_id: Mapped[uuid.UUID] = mapped_column(_fk("users.id"), primary_key=True)
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"), primary_key=True)
    role: Mapped[str] = mapped_column(String(20))
    created_at: Mapped[CreatedAt]

    __table_args__ = (
        CheckConstraint(_one_of("role", Role), name="role_valid"),
        Index("ix_memberships_org_id", "org_id"),
    )


class ApiKey(Base):
    __tablename__ = "api_keys"

    id: Mapped[UuidPk]
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"), index=True)
    name: Mapped[str] = mapped_column(String(200))
    # The visible part ("rly_live_ab12cd34"), shown in the dashboard to tell keys apart.
    prefix: Mapped[str] = mapped_column(String(32), unique=True)
    # SHA-256 of the full key. Keys are long random strings, so a fast hash is
    # safe here (unlike passwords) and keeps authentication cheap.
    key_hash: Mapped[str] = mapped_column(String(64), unique=True)
    last_used_at: Mapped[datetime | None]
    revoked_at: Mapped[datetime | None]
    created_at: Mapped[CreatedAt]


# ------------------------------------------------------------------- endpoints
class Endpoint(Base):
    __tablename__ = "endpoints"

    id: Mapped[UuidPk]
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"), index=True)
    url: Mapped[str] = mapped_column(Text)
    description: Mapped[str] = mapped_column(String(500), server_default="")
    # Event types this endpoint subscribes to. Empty means "all event types".
    event_types: Mapped[list[str]] = mapped_column(ARRAY(String(200)), server_default="{}")
    status: Mapped[str] = mapped_column(String(20), server_default=EndpointStatus.ACTIVE)
    rate_limit_per_sec: Mapped[int | None]

    # Circuit breaker. PostgreSQL is the source of truth, so breaker state
    # survives a Redis restart and is visible with plain SQL.
    breaker_state: Mapped[str] = mapped_column(String(20), server_default=BreakerState.CLOSED)
    consecutive_failures: Mapped[int] = mapped_column(server_default="0")
    breaker_opened_at: Mapped[datetime | None]

    created_at: Mapped[CreatedAt]
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now(), onupdate=func.now())

    __table_args__ = (
        CheckConstraint(_one_of("status", EndpointStatus), name="status_valid"),
        CheckConstraint(_one_of("breaker_state", BreakerState), name="breaker_state_valid"),
        CheckConstraint("char_length(url) <= 2048", name="url_length"),
        CheckConstraint(
            "rate_limit_per_sec IS NULL OR rate_limit_per_sec > 0", name="rate_limit_positive"
        ),
        CheckConstraint("consecutive_failures >= 0", name="consecutive_failures_non_negative"),
    )


class EndpointSecret(Base):
    """Signing secrets for an endpoint.

    An endpoint normally has one active secret (``expires_at`` is NULL). During a
    rotation the old secret gets an expiry in the future and a new row is added, so
    for a while messages are signed with both.
    """

    __tablename__ = "endpoint_secrets"

    id: Mapped[UuidPk]
    endpoint_id: Mapped[uuid.UUID] = mapped_column(_fk("endpoints.id"), index=True)
    # AES-GCM ciphertext. Encrypted rather than hashed, because signing with HMAC
    # needs the original secret back.
    secret_encrypted: Mapped[str] = mapped_column(Text)
    active_from: Mapped[datetime] = mapped_column(server_default=func.now())
    expires_at: Mapped[datetime | None]
    created_at: Mapped[CreatedAt]


# ---------------------------------------------------------- events & deliveries
class Event(Base):
    __tablename__ = "events"

    id: Mapped[UuidPk]
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"))
    type: Mapped[str] = mapped_column(String(200))
    payload: Mapped[dict[str, Any]]
    idempotency_key: Mapped[str | None] = mapped_column(String(255))
    created_at: Mapped[CreatedAt]

    __table_args__ = (
        # This constraint, not application code, is what makes idempotency correct
        # under concurrency: two simultaneous requests with the same key cannot
        # both insert. NULL keys never conflict with each other.
        UniqueConstraint("org_id", "idempotency_key", name="uq_events_org_id_idempotency_key"),
        Index("ix_events_org_id_created_at", "org_id", text("created_at DESC")),
    )


class Delivery(Base):
    """One event going to one endpoint. This table is the job queue."""

    __tablename__ = "deliveries"

    id: Mapped[UuidPk]
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"))
    event_id: Mapped[uuid.UUID] = mapped_column(_fk("events.id"))
    endpoint_id: Mapped[uuid.UUID] = mapped_column(_fk("endpoints.id"))
    status: Mapped[str] = mapped_column(String(20), server_default=DeliveryStatus.PENDING)
    attempts: Mapped[int] = mapped_column(server_default="0")
    next_attempt_at: Mapped[datetime] = mapped_column(server_default=func.now())
    # The claim is a lease: if a worker dies, the lease expires and the delivery
    # becomes claimable again.
    locked_until: Mapped[datetime | None]
    locked_by: Mapped[str | None] = mapped_column(String(200))
    last_error: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[CreatedAt]
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now(), onupdate=func.now())

    __table_args__ = (
        CheckConstraint(_one_of("status", DeliveryStatus), name="status_valid"),
        CheckConstraint("attempts >= 0", name="attempts_non_negative"),
        # An event is delivered to an endpoint once; replay re-queues the same row.
        UniqueConstraint("event_id", "endpoint_id", name="uq_deliveries_event_id_endpoint_id"),
        # The claim query's index. Partial, so it only contains deliveries that are
        # waiting; it stays small no matter how many finished deliveries pile up.
        Index(
            "deliveries_due",
            "next_attempt_at",
            postgresql_where=text("status IN ('pending', 'retrying')"),
        ),
        # For the sweeper that recovers deliveries whose worker died.
        Index(
            "deliveries_expired_locks",
            "locked_until",
            postgresql_where=text("status = 'in_flight'"),
        ),
        # Delivery explorer: newest first, per organisation and per endpoint.
        Index("ix_deliveries_org_id_created_at", "org_id", text("created_at DESC")),
        Index("ix_deliveries_endpoint_id_created_at", "endpoint_id", text("created_at DESC")),
    )


class Attempt(Base):
    """One HTTP request made for a delivery, and what came back."""

    __tablename__ = "attempts"

    id: Mapped[UuidPk]
    delivery_id: Mapped[uuid.UUID] = mapped_column(_fk("deliveries.id"))
    attempt_number: Mapped[int]
    started_at: Mapped[datetime] = mapped_column(server_default=func.now())
    duration_ms: Mapped[int]
    status_code: Mapped[int | None]
    # NULL when the attempt succeeded.
    error_kind: Mapped[str | None] = mapped_column(String(20))
    response_snippet: Mapped[str | None] = mapped_column(Text)
    # Stored with secrets already masked.
    request_headers: Mapped[dict[str, Any]] = mapped_column(server_default="{}")
    response_headers: Mapped[dict[str, Any] | None]

    __table_args__ = (
        CheckConstraint(
            f"error_kind IS NULL OR {_one_of('error_kind', ErrorKind)}", name="error_kind_valid"
        ),
        CheckConstraint("attempt_number >= 1", name="attempt_number_positive"),
        CheckConstraint("duration_ms >= 0", name="duration_non_negative"),
        Index("ix_attempts_delivery_id_started_at", "delivery_id", "started_at"),
    )


# ----------------------------------------------------------------------- audit
class AuditLog(Base):
    __tablename__ = "audit_log"

    id: Mapped[UuidPk]
    org_id: Mapped[uuid.UUID] = mapped_column(_fk("organizations.id"))
    # NULL when the actor was an API key, or the user has since been deleted.
    actor_user_id: Mapped[uuid.UUID | None] = mapped_column(_fk("users.id", ondelete="SET NULL"))
    action: Mapped[str] = mapped_column(String(100))
    target_type: Mapped[str] = mapped_column(String(50))
    target_id: Mapped[str] = mapped_column(String(100))
    at: Mapped[datetime] = mapped_column(server_default=func.now())
    details: Mapped[dict[str, Any]] = mapped_column(server_default="{}")

    __table_args__ = (Index("ix_audit_log_org_id_at", "org_id", text("at DESC")),)
